<section class="status" aria-live="polite"><div class="status-line"><i id="sb-phase-icon" class="bi bi-check-circle" aria-hidden="true"></i><strong id="sb-phase-title">正在读取已保存分镜…</strong><span id="sb-phase-count"></span></div><div class="progress-track" id="sb-phase-progress" hidden role="progressbar" aria-label="画面生成进度" aria-valuemin="0" aria-valuemax="100"><div id="sb-phase-fill"></div></div></section>
